"""Build the readable product and company pages from the published offer.

The owner confirmed the $0 monthly lease fee on November 8, 2026.
No unverified weights, output, or remaining commercial terms are inferred.
Run from any directory with Python 3; no third-party dependencies are needed.
"""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parents[1]
SITE = 'https://marvellabs.shop/'
SHOP = 'https://cr1bpi-qf.myshopify.com/policies/'
UPDATED = 'November 8, 2026'
TIMING = 'Target delivery: Spring 2027. Timing is not guaranteed and is confirmed separately before proceeding.'
ORG = {'@type': 'Organization', '@id': 'https://marvellabs.com/#organization', 'name': 'Marvel Labs', 'legalName': 'Marvel Labs Inc.', 'url': 'https://marvellabs.com/', 'founder': {'@type': 'Person', 'name': 'Jake Miller'}, 'address': {'@type': 'PostalAddress', 'addressLocality': 'South San Francisco', 'addressRegion': 'CA', 'addressCountry': 'US'}, 'logo': SITE+'assets/marvel-labs-wordmark.png', 'description': 'Marvel Labs develops autonomous microfactories, combining manufacturing equipment, software and production processes.', 'sameAs': ['https://www.linkedin.com/company/marvellabs/', 'https://x.com/marvellabs3d'], 'contactPoint': {'@type': 'ContactPoint', 'contactType': 'Trailer reservations and support', 'email': 'jaxon@marvellabs.com', 'url': SITE+'about.html'}}
MODELS = {'16': {'width':'7 ft','cargo':'9 ft 9½ in','price':'$44,999','intro':'A compact footprint for your route.','summary':'The narrower, shorter layout pairs the front factory concept with a rear equipment bay. Start here if overall trailer size matters most to your route and storage space.'}, '20': {'width':'8.5 ft','cargo':'13 ft 9½ in','price':'$49,999','intro':'More room behind the same factory.','summary':'The wider, longer layout adds four nominal feet of rear cargo length and 1.5 feet of trailer width compared with the 16 ft. Start here when equipment space is your priority.'}}

def metadata(title, description, path, image='assets/owner-approved-snapshot-clean-corners-v3/intro-desktop.webp', extra=None):
    graph = [ORG, {'@type':'WebPage','@id':SITE+path+'#page','url':SITE+path,'name':title,'description':description,'publisher':{'@id':ORG['@id']}}]
    if not path: graph.append({'@type':'WebSite','@id':SITE+'#website','name':'Marvel Labs — Autonomous Microfactory Trailers','url':SITE,'publisher':{'@id':ORG['@id']},'inLanguage':'en'})
    if extra: graph.append(extra)
    return f'''<title>{escape(title)} — Marvel Labs</title>
<meta name="description" content="{escape(description, quote=True)}">
<link rel="canonical" href="{SITE}{path}">
<meta property="og:type" content="website"><meta property="og:site_name" content="Marvel Labs"><meta property="og:url" content="{SITE}{path}">
<meta property="og:title" content="{escape(title, quote=True)} — Marvel Labs"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:image" content="{SITE}{image}"><meta property="og:image:alt" content="Marvel Labs microfactory trailer design illustration">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title, quote=True)} — Marvel Labs"><meta name="twitter:description" content="{escape(description, quote=True)}"><meta name="twitter:image" content="{SITE}{image}">
<script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False)}</script>'''

def footer():
    return f'''<footer class="product-footer"><nav aria-label="Footer"><a href="about.html">About &amp; contact</a><a href="specifications.html">Operating requirements</a><a href="{SHOP}terms-of-service">Reservation terms</a><a href="{SHOP}refund-policy">Refunds</a><a href="{SHOP}privacy-policy">Privacy</a></nav><p>© 2026 Marvel Labs Inc. · marvellabs.shop is Marvel Labs’ trailer product and reservation site. </p></footer>'''

def page(path, title, description, body, image=None, extra=None):
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0a0e10">{metadata(title,description,path,image or 'assets/owner-approved-snapshot-clean-corners-v3/intro-desktop.webp',extra)}<link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="product-pages.css?v=20261108"><script type="module" src="campaign-links.js?v=launch-20261108"></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="product-header"><a class="brand" href="./">MARVEL LABS</a><nav aria-label="Main navigation"><a href="trailer-16.html">16 ft</a><a href="trailer-20.html">20 ft</a><a href="economics.html">Plans &amp; earnings</a><a href="about.html">Company</a><a href="reserve.html">Reserve ↗</a></nav></header><main id="main">{body}</main>{footer()}</body></html>'''
    (ROOT/path).write_text(html+'\n')

def faq(question, answer):
    return f'<details><summary>{question}</summary><p>{answer}</p></details>'

def model(size, m):
    other = '20' if size == '16' else '16'
    title=f'{size} ft × {m["width"]} microfactory trailer'
    description=f'Explore the Marvel Labs {size} ft trailer: {m["width"]} nominal width, {m["cargo"]} rear cargo layout and {m["price"]} preview Buy price. $100 refundable reservation deposit.'
    properties=[{'@type':'PropertyValue','name':name,'value':value} for name,value in [('Nominal trailer length',size+' ft'),('Nominal trailer width',m['width']),('Nominal enclosed factory length','6 ft 2½ in'),('Nominal rear cargo length',m['cargo']),('Development status','Design preview; final usable dimensions and ratings pending')]]
    product={'@type':'Product','@id':SITE+f'trailer-{size}.html#product','name':f'Marvel Labs {size} ft microfactory trailer','model':f'{size} ft','description':description,'url':SITE+f'trailer-{size}.html','image':SITE+f'assets/owner-approved-trailer-v1/thumb-{size}.png','brand':{'@type':'Brand','name':'Marvel Labs'},'manufacturer':{'@id':ORG['@id']},'additionalProperty':properties}
    # No Offer: the trailer price is a preview, and $100 buys only a reservation.
    body=f'''<section class="hero hero-grid"><div><p class="eyebrow">Marvel Labs · {size} ft × {m['width']} · Design preview</p><h1>{size} ft<br>microfactory trailer.</h1><p class="lead">{m['summary']}</p><p class="price">{m['price']} <span class="note">preview Buy price</span></p><div class="actions"><a class="button" href="reserve.html?size={size}">Reserve the {size} ft · $100 deposit ↗</a><a href="trailer-{other}.html">Compare the {other} ft</a></div><p class="note">Fully refundable reservation deposit, not the trailer price or a monthly lease payment. {TIMING}</p></div><figure><img class="product-image" src="assets/owner-approved-trailer-v1/thumb-{size}.png" width="768" height="512" alt="{size} ft Marvel Labs trailer design in Mirror Graphite" fetchpriority="high"><figcaption>Design rendering · Mirror Graphite. Equipment and clearances require confirmation.</figcaption></figure></section>
<section><p class="eyebrow">The layout</p><h2>{size} feet. Two working areas.</h2><div class="layout" role="img" aria-label="Nominal layout: front enclosed factory 6 feet 2 and a half inches; rear cargo {m['cargo']}; trailer width {m['width']}"><div class="factory" style="flex:6.2083">Enclosed factory<span>6 ft 2½ in</span></div><div class="cargo" style="flex:{int(size)-6.2083}">Rear equipment bay<span>{m['cargo']}</span></div></div><p class="note">Concept plan, not a loading or engineering drawing. Nominal layout lengths do not establish usable interior clearance.</p><div class="grid"><dl class="specs"><div><dt>Nominal footprint</dt><dd>{size} ft × {m['width']}</dd></div><div><dt>Enclosed factory</dt><dd>6 ft 2½ in</dd></div><div><dt>Rear cargo length</dt><dd>{m['cargo']}</dd></div><div><dt>Exterior preview</dt><dd>Mirror Graphite</dd></div></dl><article class="card"><h3>Will your equipment fit?</h3><p>{'Use the 16 ft layout to assess one mower and hand tools.' if size=='16' else 'Use the 20 ft layout to assess a larger mower-and-tool loadout.'} These are planning examples, not verified equipment capacities.</p><p>Measure each item’s width, length, height and weight. Usable interior width, door and ramp openings, ramp rating, axle loads and remaining payload are pending.</p><a href="specifications.html">Check towing and operating requirements ↗</a></article></div></section>
<section><p class="eyebrow">Choose a plan</p><h2>Purchase or proposed lease.</h2><div class="grid"><article class="card"><h3>Buy</h3><p class="price">{m['price']}</p><p>Preview trailer purchase price. Proposed operator share: 75% of profit from products sold; Marvel’s share: 25%.</p></article><article class="card"><h3>Lease</h3><p class="price">$0 <span class="note">monthly lease fee</span></p><p>No upfront trailer purchase. The operator receives 25% of profit from products sold; Marvel receives 75%.</p><p>The $100 refundable reservation deposit is separate. Operating costs, duration, insurance, maintenance and return obligations are confirmed in the final written agreement.</p></article></div><p>Both choices use the same $100 fully refundable reservation deposit. It does not authorize an automatic balance payment or establish the final purchase or lease terms.</p><a href="economics.html">Read how profit sharing and costs work ↗</a></section>
<section><p class="eyebrow">Factory and availability</p><h2>The same factory concept in both sizes.</h2><p>The planned process uses suitable collected grass to make a proposed 20 × 20 inch sink, with preparation, forming, quality checks and packaging inside the front factory. A larger trailer adds equipment space; it does not establish a higher production rate.</p><p>Grass is the development focus. Accepted feedstocks, moisture limits, contamination tolerances, measured output, power demand and runtime are pending validation. Leaves and food waste are not published as validated inputs.</p><p>{TIMING}</p><a href="validation.html">See development status and evidence still needed ↗</a></section>
<section><h2>Before reserving.</h2>{faq('Can my truck tow it?','Tow-vehicle compatibility cannot be confirmed yet. Empty and loaded weight, GVWR, tongue weight, brakes and hitch requirements are pending. Confirm the complete loaded configuration and vehicle ratings before towing.')}{faq('Does $100 buy or lease the trailer?',f'No. It is a one-time refundable reservation deposit. The {size} ft preview Buy price is {m["price"]}; final purchase and lease terms are separate. The Lease plan has a $0 monthly lease fee. Operating costs and other lease obligations are separate and confirmed in the final written agreement.')}{faq('Are the films production demonstrations?','The website films are design and workflow illustrations. They are not measurements of output, quality, operating cost or unattended runtime. See the development-status page for what has and has not been published.')}{faq('How do I cancel a reservation?',f'Email <a href="mailto:jaxon@marvellabs.com">jaxon@marvellabs.com</a> with your Shopify order number. See the current <a href="{SHOP}refund-policy">refund policy</a>.')}{faq('Who supplies and maintains the system?','Marvel’s proposed package includes the trailer factory, production inputs, packaging, shipping arrangements, buyer coordination and software. Consumables, maintenance responsibilities, warranty and downtime procedures require the final operating agreement.')}</section><section><h2>Choose your footprint.</h2><div class="actions"><a class="button" href="reserve.html?size={size}">Reserve the {size} ft · $100 deposit ↗</a><a class="button secondary" href="mailto:jaxon@marvellabs.com">Ask a trailer question</a></div><p class="note">Updated {UPDATED}. Final specifications, pricing, availability and terms are confirmed separately.</p></section>'''
    page(f'trailer-{size}.html',title,description,body,f'assets/owner-approved-trailer-v1/thumb-{size}.png',product)

for size, details in MODELS.items(): model(size,details)

page('economics.html','Trailer plans, deposits and earnings','Understand the $100 refundable reservation deposit, preview Buy prices, proposed profit shares and costs awaiting final agreement.',f'''<section class="hero"><p class="eyebrow">Plans &amp; earnings</p><h1>From a product sold<br>to your share of profit.</h1><p class="lead">Production, sales, calculated profit and payouts are different events. The proposed operator share applies to profit from products sold.</p></section><section><h2>What you pay, and when.</h2><div class="table-wrap"><table><thead><tr><th>Item</th><th>Published position</th></tr></thead><tbody><tr><th>Reservation</th><td>$100 USD, one time and fully refundable. Live checkout is hosted by Shopify. The checkout displays the final total.</td></tr><tr><th>Buy</th><td>Preview prices: 16 ft $44,999; 20 ft $49,999. The reservation deposit is intended to be credited toward a purchased trailer’s final price. The final agreement confirms pricing, taxes, delivery and other charges.</td></tr><tr><th>Lease</th><td>$0 monthly lease fee and no upfront trailer purchase. The $100 refundable reservation deposit is separate. Operating costs, term, insurance, maintenance, deposit treatment and return conditions are confirmed in the final written agreement.</td></tr><tr><th>Balance</th><td>No remaining balance is charged automatically. A reservation is separate from a final purchase or lease agreement.</td></tr></tbody></table></div><p><a href="{SHOP}terms-of-service">Current reservation terms</a> · <a href="{SHOP}refund-policy">Current refund policy</a></p></section><section><h2>How profit sharing is intended to work.</h2><div class="grid"><article class="card"><h3>Buy</h3><p class="price">75% operator / 25% Marvel</p><p>Proposed split of product profit.</p></article><article class="card"><h3>Lease</h3><p class="price">25% operator / 75% Marvel</p><p>$0 monthly lease fee. Proposed split of profit from products sold; operating costs and other obligations are separate.</p></article></div><p class="callout">Operator earnings = the agreed profit on products sold × the operator’s plan share. This is not a share of the selling price and is not earned simply by producing an item.</p><p>The final agreement must define deductible costs, accepted sales, rejected or returned products, unsold inventory, shipping, refunds, settlement timing and payout timing. Those definitions have not yet been published as final terms; a net earnings forecast would be premature.</p></section><section><h2>The $300 example.</h2><p class="price">20 sales × $15 = $300</p><p>Illustration only: all 20 sinks sell at $15 gross operator earnings each, before the operator’s expenses. It is not a production test, a forecast, or a projection for either plan. The $15 amount is an illustrative input, not a calculated payout under the unfinished profit agreement.</p><p>Actual earnings depend on sales, costs and the agreed profit calculation. Production, demand and earnings are not guaranteed.</p></section><section><h2>Responsibilities to confirm.</h2><p>Marvel’s proposed package combines factory inputs, packaging, shipping arrangements, buyer coordination and software. The operator brings their own landscaping equipment. The final agreement must assign consumables, power, maintenance, insurance, storage, shipping, damage, returns and downtime costs.</p><p>{TIMING}</p><div class="actions"><a class="button" href="reserve.html">Review a $100 reservation ↗</a><a href="mailto:jaxon@marvellabs.com">Ask about the agreement</a></div></section>''')

requirements=[('Towing','Empty and loaded weights, GVWR, axle ratings, tongue weight, brakes, hitch and tow-vehicle requirements.'),('Equipment fit','Usable interior dimensions, door/ramp openings, ramp rating, available payload and verified representative loadouts.'),('Power','Power source and capacity, charging supply, peak demand, energy per product and runtime under stated conditions.'),('Feedstock','Accepted grass types, moisture range, contaminants, preparation, storage and rejection criteria. Leaves and food waste are not validated inputs in the published material.'),('Production','Measured accepted output, cycle time, quality/reject rate, uptime, downtime and test conditions.'),('Service and safety','Operator training, maintenance responsibilities, consumables, warranty, fault response and downtime procedures.')]
rows=''.join(f'<tr><th>{q}</th><td>{v}</td><td class="pending">Pending publication / validation</td></tr>' for q,v in requirements)
page('specifications.html','Trailer specifications and operating requirements','Compare nominal trailer layouts and see which towing, payload, power, feedstock and service specifications remain pending.',f'''<section class="hero"><p class="eyebrow">Specifications &amp; operating requirements</p><h1>Plan with published dimensions.<br>Verify the working limits.</h1><p class="lead">The dimensions below describe the current design. They are not certified usable clearances, payload ratings or towing approval.</p></section><section><h2>Current nominal layouts.</h2><div class="table-wrap"><table><thead><tr><th>Dimension</th><th>16 ft</th><th>20 ft</th></tr></thead><tbody><tr><th>Trailer footprint</th><td>16 ft × 7 ft</td><td>20 ft × 8.5 ft</td></tr><tr><th>Enclosed factory length</th><td>6 ft 2½ in</td><td>6 ft 2½ in</td></tr><tr><th>Rear cargo length</th><td>9 ft 9½ in</td><td>13 ft 9½ in</td></tr></tbody></table></div><p><a href="trailer-16.html">16 ft model details</a> · <a href="trailer-20.html">20 ft model details</a></p></section><section><h2>Before choosing a working configuration.</h2><div class="table-wrap"><table><thead><tr><th>Question</th><th>Information needed</th><th>Status</th></tr></thead><tbody>{rows}</tbody></table></div><p>Neither model has a published verified mower capacity. Compare equipment dimensions and weights only after usable clearances and load ratings are confirmed. A reservation does not establish these specifications.</p></section><section><h2>Ask about your equipment and route.</h2><p>Send the trailer team your equipment dimensions and weights, tow-vehicle configuration and service area. Final compatibility and operating requirements must be confirmed before use.</p><a class="button" href="mailto:jaxon@marvellabs.com">Contact the trailer team ↗</a><p class="note">Updated {UPDATED}. <a href="validation.html">Development and validation status</a>.</p></section>''')

page('validation.html','Trailer development and validation status','Dated status of Marvel Labs trailer design illustrations, published specifications, operating tests and evidence still pending.',f'''<section class="hero"><p class="eyebrow">Development status · {UPDATED}</p><h1>What the website shows.<br>What still needs measurement.</h1><p class="lead">The trailer is a product under development. Design renderings and workflow animations explain the intended system; they do not establish measured production performance.</p></section><section><h2>Published today.</h2><ul class="validation-list"><li>Design illustrations for 16 ft and 20 ft trailers, with nominal factory and rear cargo layout lengths.</li><li>A proposed process for converting suitable collected grass into a 20 × 20 inch sink.</li><li>Preview Buy pricing and proposed operator shares of profit from products sold.</li><li>An interactive Marvel Crew app demonstration using example data.</li><li>A live Shopify flow for a one-time $100 refundable reservation deposit.</li></ul></section><section><h2>Evidence still to publish.</h2><ul class="validation-list"><li>A dated physical production demonstration with input condition, cycle time and accepted output.</li><li>Product test results, reject rate, operating hours and downtime under stated conditions.</li><li>Power source, energy consumption, charging requirements and measured runtime.</li><li>Validated feedstock acceptance limits and preparation requirements.</li><li>Verified trailer weights, usable clearances, towing ratings and representative loadouts.</li><li>Final profit calculation, operating responsibilities, warranty and service procedures.</li></ul><p>No measured trailer throughput, validated operating-cost result or guaranteed return is claimed by these pages. Missing values are <a href="specifications.html">listed as pending</a>.</p></section><section><h2>How to read the visuals.</h2><p>The homepage films and model images are design and workflow illustrations. App counts, locations, camera views and earnings are example data. The $300 earnings example assumes 20 completed sales at an illustrative $15 gross operator earnings per sale, before operator expenses; it is not a test result or a projection for either plan.</p><p>{TIMING}</p><a class="button" href="mailto:jaxon@marvellabs.com">Ask for current validation information ↗</a></section>''')

page('about.html','About Marvel Labs and trailer support','Marvel Labs Inc. operates marvellabs.shop for trailer products and reservations. Find the corporate website, official profiles and reservation support.',f'''<section class="hero"><p class="eyebrow">Marvel Labs Inc.</p><h1>One company.<br>A trailer built around your route.</h1><p class="lead">Marvel Labs develops autonomous microfactories, combining manufacturing equipment, software and production processes.</p><p><strong>marvellabs.shop is Marvel Labs’ trailer product and reservation site.</strong> <a href="https://marvellabs.com/">marvellabs.com</a> describes the broader company and manufacturing platform. The trailer’s proposed Buy and Lease plans are described here and confirmed in their own final agreements.</p></section><section><h2>Company and trailer team.</h2><div class="grid"><article class="card"><h3>Marvel Labs Inc.</h3><p>Founder: Jake Miller. <a href="https://marvellabs.com/">Company background and platform ↗</a></p><p>Headquartered in South San Francisco, California, as listed on the <a href="https://marvellabs.com/">corporate website</a>. The team also has an operating base near Fort Wayne, Indiana.</p><p>Contact the trailer team for current service-area availability, team introductions or a demonstration. Visits and deliveries require an arrangement in advance.</p></article><article class="card"><h3>Reservations and support</h3><p><a href="mailto:jaxon@marvellabs.com">jaxon@marvellabs.com</a></p><p>For an existing reservation, include your Shopify order number. The team can help with selection changes, cancellation and refund requests.</p><p>General company inquiries: <a href="mailto:hello@marvellabs.com">hello@marvellabs.com</a>.</p></article></div></section><section><h2>Partnerships and media.</h2><p>For sponsorships, field collaborations, publications or campaign materials, start with the current facts and contact the trailer team.</p><div class="actions"><a href="partners.html">Partnership &amp; sponsorship inquiries ↗</a><a href="media.html">Media information &amp; images ↗</a></div></section><section><h2>Official company profiles.</h2><div class="actions"><a href="https://www.linkedin.com/company/marvellabs/">Marvel Labs on LinkedIn ↗</a><a href="https://x.com/marvellabs3d">Marvel Labs on X ↗</a><a href="https://marvellabs.com/">Corporate website ↗</a></div></section><section><h2>Current reservation policies.</h2><p>The authoritative reservation and data-processing policies are published on Marvel Labs’ Shopify store.</p><div class="actions"><a href="{SHOP}terms-of-service">Reservation terms</a><a href="{SHOP}refund-policy">Refund policy</a><a href="{SHOP}privacy-policy">Privacy policy</a><a href="{SHOP}shipping-policy">Shipping policy</a></div><p class="note">The store is cr1bpi-qf.myshopify.com. Payments and order confirmations are handled there. A reservation does not authorize an automatic trailer balance charge.</p></section>''')

page('reservation-help.html','Reservation help','Get help with a real Shopify reservation, selection changes, confirmation and refunds for your $100 trailer deposit.',f'''<section class="hero narrow"><p class="eyebrow">Reservation help</p><h1>Your reservation.<br>Clear next steps.</h1>{faq('How do I reserve?','Select your trailer size and Buy or Lease plan, review the reservation and current policies, then continue to Shopify. Enter contact and payment details there. Shopify confirms the order after successful payment.')}{faq('Will checkout charge me?','Yes. This is a live checkout for a one-time $100 USD refundable reservation deposit. Applicable tax, if any, is calculated at checkout. Review Shopify’s final total before paying. Any Shop Pay installment option applies to this deposit checkout; it is not the $0 monthly trailer lease or financing for the full trailer price. It is not the full trailer price or a lease payment, and no remaining balance is charged automatically.')}{faq('How do I change or cancel my reservation?',f'Contact <a href="mailto:jaxon@marvellabs.com">jaxon@marvellabs.com</a> with your Shopify order number. Cancellations are refunded in full to the original payment method under the <a href="{SHOP}refund-policy">current refund policy</a>.')}{faq('Where is my confirmation?','Shopify handles order confirmation. Returning to this website does not confirm or cancel payment. If you are unsure whether an order completed, check your Shopify confirmation and contact reservation support before trying again.')}{faq('What are the final lease terms?','The Lease plan has a $0 monthly lease fee. The $100 refundable reservation deposit is separate. The operator receives 25% of profit from products sold. Operating costs, duration, maintenance, insurance and return obligations are confirmed in the final written agreement. See the plans and earnings page.')}{faq('When will my trailer arrive?',TIMING)}<p><a class="button" href="reserve.html">Return to reservations ↗</a></p></section>''')

technology_terms = [
    ('Physical AI', 'Software that perceives and acts in the physical world through machines. Marvel Labs applies this idea to manufacturing; the trailer’s complete autonomous workflow is still being validated.'),
    ('Autonomous microfactory', 'A compact production system designed to coordinate material preparation, forming, inspection and packaging. Autonomous describes the development goal; operators still load material, handle packages and follow operating procedures.'),
    ('Mobile manufacturing', 'Manufacturing equipment packaged in a trailer so production can be brought to an operator’s route. Final towing ratings, setup requirements and operating conditions are pending.'),
    ('Distributed manufacturing', 'Production spread across smaller locations instead of one central factory. The trailer offering explores this model with landscaping crews and coordinated product sales.'),
    ('Biomass upcycling', 'Using biological material as an input for higher-value products. Suitable collected grass is the trailer’s development focus; accepted moisture, contaminants and preparation limits are pending validation.'),
    ('Circular manufacturing', 'Designing production around reuse of materials. Turning collected grass into products is the intended approach; no quantified waste-reduction, carbon-saving or lifecycle result is claimed.'),
]
term_cards = ''.join(f'<article class="card"><h3 id="term-{i}">{escape(name)}</h3><p>{escape(description)}</p></article>' for i,(name,description) in enumerate(technology_terms))
terms_schema = {'@type':'DefinedTermSet','@id':SITE+'technology.html#terms','name':'Marvel Labs trailer technology terms','hasDefinedTerm':[{'@type':'DefinedTerm','@id':SITE+f'technology.html#term-{i}','name':name,'description':description,'inDefinedTermSet':SITE+'technology.html#terms'} for i,(name,description) in enumerate(technology_terms)]}
page('technology.html','Physical AI and autonomous microfactory technology','Understand Marvel Labs’ mobile manufacturing concept: physical AI, autonomous microfactories, grass feedstocks, connected software and the capabilities still being validated.',f'''<section class="hero narrow"><p class="eyebrow">Technology, explained</p><h1>Physical AI.<br>A factory built for your route.</h1><p class="lead">Marvel Labs develops autonomous microfactories: manufacturing equipment, software and production processes brought together in a compact system.</p><p>The trailer concept puts that system beside the equipment a landscaping crew already carries. It is designed to turn suitable collected grass into products, with software connecting production, product sales and operator earnings.</p><p class="note">Development status reviewed {UPDATED}. The films illustrate the design and intended workflow. Measured trailer output and validated operating requirements have not yet been published.</p></section><section><h2>What the terms mean for this trailer.</h2><div class="grid">{term_cards}</div></section><section><h2>Automation, robotics and computer vision.</h2><p>The intended workflow prepares material, forms a product, checks it and packages it. Robotics and automation describe the physical handling and coordinated machinery. Computer vision describes software interpreting camera images, for example to support inspection. A camera feed alone does not demonstrate automated quality control.</p><p>These are technology concepts, not a published specification for every trailer subsystem. Specific sensors, controls, inspection accuracy, throughput, human interventions and downtime need documented validation. The current <a href="validation.html">development status</a> and <a href="specifications.html">pending operating requirements</a> explain what is and is not established.</p></section><section><h2>Connected software and the assistant.</h2><p>Marvel Crew’s proposed features include production status, camera views, products made and sold, operator earnings and payouts. The public app screens use illustrative data. The website assistant provides guided answers about the trailer and reservation offer.</p>{faq('Does the website assistant control the factory?','No. It does not operate machinery, access live cameras or complete payments. The public website uses prepared answers; it does not establish that an LLM controls the trailer.')}{faq('Where do LLMs fit?','A large language model (LLM) can provide a conversational software interface. That is a different role from machine control, inspection and safety systems. No specific LLM integration or model provider is confirmed for the delivered trailer on these pages.')}{faq('Are the animations a production demonstration?','They are rendered design and workflow illustrations. A measured demonstration requires an actual production run, its test conditions and recorded results. See the development status page for the evidence still to be published.')}</section><section><h2>Technology with a clear business offer.</h2><p>The corporate site describes Marvel Labs’ broader manufacturing platform and Robotics-as-a-Service (RaaS) approach. This site describes the trailer’s own Buy and Lease plans. The Lease plan has a <strong>$0 monthly lease fee</strong>; the operator’s proposed share is 25% of the agreed profit from products sold. Operating obligations and the final profit calculation are confirmed in the written agreement.</p><p>The <strong>$100 refundable reservation deposit</strong> is separate from the lease fee and trailer purchase price. {TIMING}</p><div class="actions"><a class="button" href="overview.html">Explore the trailer ↗</a><a href="economics.html">Read the plans and earnings</a><a href="https://marvellabs.com/">Explore the corporate platform ↗</a></div></section>''',extra=terms_schema)

for old, target, label in [('privacy.html','privacy-policy','Privacy policy'),('terms.html','terms-of-service','Reservation terms'),('reservation-agreement.html','terms-of-service','Reservation agreement'),('reservation-refunds.html','refund-policy','Refund policy')]:
    url=SHOP+target
    (ROOT/old).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{label} — Marvel Labs</title><meta http-equiv="refresh" content="0;url={url}"><link rel="canonical" href="{url}"><meta name="robots" content="noindex,follow"><link rel="stylesheet" href="product-pages.css?v=20261108"></head><body><main><h1>{label}</h1><p>Marvel Labs’ current {label.lower()} is published on our Shopify store. This replaces the obsolete local demonstration policy.</p><p><a href="{url}">Read the current {label.lower()} ↗</a></p><p><a href="reservation-help.html">Reservation support</a></p></main></body></html>\n''')

page('partners.html','Partnerships and sponsorship inquiries','Discuss sponsorship, equipment, materials, field development and media partnerships with Marvel Labs. Contact the trailer team to agree scope and terms.',f'''<section class="hero narrow"><p class="eyebrow">Partners &amp; sponsors</p><h1>Help shape the next work trailer.</h1><p class="lead">Marvel Labs is developing a mobile microfactory concept for landscaping crews. We welcome conversations with equipment and material suppliers, prospective field collaborators, creators and organizations interested in the work.</p><div class="actions"><a class="button" href="mailto:jaxon@marvellabs.com?subject=Marvel%20Labs%20partnership%20inquiry">Discuss a partnership ↗</a><a href="media.html">Media information &amp; images</a></div></section><section><h2>Start with a specific project.</h2><div class="grid"><article class="card"><h3>Equipment and materials</h3><p>Describe the equipment, component, feedstock or material you would like the team to evaluate and the support you can provide.</p></article><article class="card"><h3>Field development</h3><p>Tell us about your landscaping operation, location, route and equipment. Field participation, responsibilities and availability require a separate agreement.</p></article><article class="card"><h3>Creators, events and sponsors</h3><p>Propose a story, event, sponsorship or demonstration. Include the audience, format, dates, requested deliverables and budget or in-kind contribution.</p></article></div></section><section class="narrow"><h2>A clear scope before a commitment.</h2><p>Send your company or organization, contact name, project idea, timing and proposed contribution to <a href="mailto:jaxon@marvellabs.com">jaxon@marvellabs.com</a>. Opening an email does not submit an inquiry; send it from your email app.</p><p>Sponsorship packages, fees, usage rights, deliverables and exclusivity are agreed individually in writing. No audience size, campaign result or production performance is promised on this page.</p><p>A trailer reservation is separate from a partnership. The $100 refundable deposit does not purchase sponsorship, endorsement rights or priority access to a demonstration.</p></section><section class="narrow"><h2>Start with the current evidence.</h2><p>Animations show the intended design and workflow. The complete trailer production cycle, output and operating requirements remain under development. {TIMING}</p><div class="actions"><a href="validation.html">Read the development status ↗</a><a href="specifications.html">Operating requirements</a><a href="about.html">Company &amp; contact</a></div></section>''')

page('media.html','Marvel Labs trailer media information and images','Official Marvel Labs trailer descriptions, reservation facts, concept images and media contact for publications, advertising and partner conversations.',f'''<section class="hero narrow"><p class="eyebrow">Media information · Updated {UPDATED}</p><h1>The trailer story.<br>The facts behind it.</h1><p class="lead">Marvel Labs develops autonomous microfactories, combining manufacturing equipment, software and production processes. Its trailer concept is designed for landscaping crews, pairing equipment space with a system intended to turn suitable collected grass into products.</p><p>marvellabs.shop is Marvel Labs’ official trailer product and reservation site. The broader corporate platform is at <a href="https://marvellabs.com/">marvellabs.com</a>.</p><div class="actions"><a class="button" href="mailto:jaxon@marvellabs.com?subject=Marvel%20Labs%20media%20inquiry">Contact the trailer team ↗</a><a href="partners.html">Partnership inquiries</a></div></section><section><h2>Current offer at a glance.</h2><div class="grid"><article class="card"><h3>Two design footprints</h3><p>16 ft × 7 ft and 20 ft × 8.5 ft nominal trailers. Final usable clearances, towing ratings and payload are pending.</p><p><a href="trailer-16.html">16 ft details</a> · <a href="trailer-20.html">20 ft details</a></p></article><article class="card"><h3>Reservations</h3><p>A one-time $100 USD refundable deposit is paid through Shopify. It is separate from the trailer price and monthly lease fee, and does not authorize an automatic balance charge.</p><p><a href="reservation-help.html">Reservation help and current policies</a></p></article><article class="card"><h3>Buy or Lease</h3><p>Preview Buy prices: $44,999 for 16 ft and $49,999 for 20 ft. Lease: $0 monthly lease fee. Proposed operator profit shares are 75% for Buy and 25% for Lease, on products sold under the agreed profit calculation. Operating costs and obligations still apply.</p><p><a href="economics.html">Read the complete plan explanation</a></p></article></div><p class="note">{TIMING} Final specifications and purchase or lease terms are confirmed separately.</p></section><section><h2>Images and credit.</h2><figure><img src="assets/owner-approved-snapshot-clean-corners-v3/intro-desktop.webp" width="2304" height="1024" loading="lazy" alt="Marvel Labs trailer design illustration"><figcaption>Marvel Labs trailer concept. Credit: Marvel Labs. Design illustration; final specifications may change.</figcaption></figure><div class="actions"><a href="assets/owner-approved-snapshot-clean-corners-v3/intro-desktop.webp" download>Download trailer concept image</a><a href="assets/marvel-labs-wordmark.png" download>Download Marvel Labs wordmark</a></div><p>Retain the concept caption when describing the trailer. Contact the team to confirm usage rights, publication context, paid placement, co-branding or endorsement requests. A downloadable file does not establish a partnership.</p></section><section class="narrow"><h2>Keep the evidence and the illustration distinct.</h2><p>The films are design animations. App screens contain example data. Suitable collected grass is the development focus; accepted feedstock limits, measured throughput, runtime and reliability are not yet published.</p><p>The $300-per-day illustration assumes 20 products sell at $15 gross operator earnings each, before operator expenses. It is not measured output, a forecast or a plan-specific return. Keep those assumptions with the number if you use it.</p><p>Use the <a href="validation.html">development status</a>, <a href="specifications.html">operating requirements</a> and <a href="technology.html">technology explanation</a> as the current source pages. Ask the team for dated demonstrations, build photographs and test reports before describing performance as proven.</p></section>''')

urls=['','overview.html','trailer-16.html','trailer-20.html','reserve.html','about.html','specifications.html','economics.html','validation.html','reservation-help.html','technology.html','partners.html','media.html']
